<script setup>
import{onMounted,reactive,ref}from'vue';import{request}from'../api';const tasks=ref([]),summary=ref({}),error=ref('');const tomorrow=()=>{const d=new Date(Date.now()+86400000);return d.toISOString().slice(0,19)};const form=reactive({taskNo:'INS-'+Date.now(),planNo:'PLAN-DAY',routeName:'生产车间日巡检',assignee:'巡检员',plannedPoints:3,dueAt:tomorrow()});const hash='a'.repeat(64);async function load(){[tasks.value,summary.value]=await Promise.all([request('/api/core/inspection/tasks'),request('/api/core/inspection/summary')])}async function create(){try{await request('/api/core/inspection/tasks',{method:'POST',body:JSON.stringify(form)});form.taskNo='INS-'+Date.now();await load()}catch(e){error.value=e.message}}async function act(t,a){try{let path=`/api/core/inspection/tasks/${t.id}/${a}`,body;if(a==='point'){path=`/api/core/inspection/tasks/${t.id}/points`;body={pointCode:'POINT-'+(t.completedPoints+1),passed:true,reading:'检查正常',evidenceHash:hash}}if(a==='close')path=`/api/admin/core/inspection/tasks/${t.id}/close`;await request(path,{method:'POST',body:body?JSON.stringify(body):undefined});await load()}catch(e){error.value=e.message}}onMounted(load)
</script><template><section class="head"><div><span>FIELD INSPECTION</span><h3>巡检任务调度台</h3><p>点位扫码与证据哈希形成不可抵赖记录，未完成点位或隐患时禁止关闭。</p></div><div class="metric"><b>{{summary.totalTasks||0}}</b><small>任务</small><b>{{summary.openHazards||0}}</b><small>未销项隐患</small></div></section><p class="err" v-if="error">{{error}}</p><form class="create" @submit.prevent="create"><input v-model="form.taskNo"><input v-model="form.routeName"><input v-model="form.assignee"><input v-model.number="form.plannedPoints" type="number" min="1"><button>下发任务</button></form><section class="cards"><article v-for="t in tasks" :key="t.id"><div><code>{{t.taskNo}}</code><h4>{{t.routeName}}</h4><p>{{t.assignee}} · {{t.completedPoints}} / {{t.plannedPoints}} 个点位 · 异常 {{t.failedPoints}}</p></div><b>{{t.status}}</b><div class="progress"><i :style="{width:(t.completedPoints/t.plannedPoints*100)+'%'}"></i></div><div><button v-if="t.status==='PLANNED'" @click="act(t,'start')">开始巡检</button><button v-if="t.status==='IN_PROGRESS'&&t.completedPoints<t.plannedPoints" @click="act(t,'point')">提交点位</button><button v-if="t.status==='IN_PROGRESS'&&t.completedPoints===t.plannedPoints" @click="act(t,'close')">关闭任务</button></div></article></section></template>
<style scoped>.head,.create,.cards{background:#fff;border:1px solid #dce2df;margin-top:20px;padding:24px}.head{display:flex;justify-content:space-between}.head span{font-size:11px;letter-spacing:.15em;color:#a56c24}.head h3{margin:6px 0}.head p{margin:0;color:#68777c}.metric{display:grid;grid-template-columns:auto auto;gap:3px 12px}.metric b{font-size:24px}.create{display:grid;grid-template-columns:1fr 2fr 1fr 1fr auto;gap:10px}.create input{padding:10px;border:1px solid #ccd6d2}.create button,.cards button{border:0;background:#235a74;color:white;padding:8px 12px}.cards article{display:grid;grid-template-columns:1fr 120px 180px auto;gap:15px;align-items:center;padding:15px 0;border-top:1px solid #edf0ef}.cards h4{margin:4px 0}.cards p{margin:0;color:#68777c}.progress{height:6px;background:#e7ecea}.progress i{display:block;height:100%;background:#2f7d61}.err{color:#a03f38}@media(max-width:800px){.create,.cards article{grid-template-columns:1fr}.metric{display:none}}</style>
